   if(m==='HUNT')searchSelectedDeck(g,actor,p,ids('cards'),{reveal:false});
   if(m==='PHANTOM')for(const [ident,count] of Object.entries(action.selections?.allocation||{}))counters(g,actor,find(g,ident).card,count,{attack:true});
